// ===== types.ts =====
// Data contracts shared by every kernel operation. Field names match
// src/auditable_design/schemas.py so files written by the flow can be
// compared with files written by the Python pipeline.

interface Utterance {
  utterance_id: string;
  source_type: string; // e.g. "app_review", "nps_comment", "interview", "survey", "complaint"
  text: string;
  date?: string | null;
  segment?: string | null;
  rating?: number | null;
  source_ref?: string | null; // link or locator of the original
}

interface ComplaintNode {
  node_id: string;
  node_type: string;
  verbatim_quote: string;
  quote_start: number;
  quote_end: number;
}

interface ComplaintEdge {
  src: string;
  dst: string;
  relation: string;
}

interface ComplaintGraph {
  review_id: string;
  nodes: ComplaintNode[];
  edges: ComplaintEdge[];
}

interface InsightCluster {
  cluster_id: string;
  label: string;
  member_review_ids: string[];
  centroid_vector_ref: string;
  representative_quotes: string[];
  ui_context?: string | null;
  html?: string | null;
  screenshot_ref?: string | null;
  representative_review_ids?: string[];
}

interface HeuristicViolation {
  heuristic: string;
  violation: string;
  severity: number;
  evidence_review_ids: string[];
  reasoning: string;
}

interface AuditVerdict {
  verdict_id: string;
  cluster_id: string;
  skill_id: string;
  relevant_heuristics: HeuristicViolation[];
  native_payload_ref?: string | null;
  produced_at: string;
  claude_model: string;
  skill_hash: string;
}

interface SkillTension {
  skill_a: string;
  skill_b: string;
  axis: string;
  resolution: string;
}

interface ReconciledVerdict {
  cluster_id: string;
  ranked_violations: HeuristicViolation[];
  tensions: SkillTension[];
}

interface PriorityScore {
  cluster_id: string;
  dimensions: { [k: string]: number };
  meta_weights: { [k: string]: number };
  weighted_total: number;
  validation_passes: number;
  validation_delta: number;
}

interface DesignDecision {
  decision_id: string;
  principle_id: string;
  description: string;
  before_snapshot: string;
  after_snapshot: string;
  resolves_heuristics: string[];
}

interface OptimizationIteration {
  iteration_id: string;
  run_id: string;
  iteration_index: number;
  parent_iteration_id: string | null;
  design_artifact_ref: string;
  scores: { [skill: string]: { [heuristic: string]: number } };
  reasoning: string;
  accepted: boolean;
  regression_reason: string | null;
  delta_per_heuristic: { [heuristic: string]: number };
  informing_review_ids: string[];
  recorded_at: string;
}

// Every operation returns this envelope (serialised to a string for the
// flow). `ok:false` means the input was wrong (unknown op, missing key):
// stop the run. A model response that cannot be used comes back as
// `ok:true` with `result.status` "fallback" (or a quarantine record) and
// is written to the run folder like any other result.
interface KernelResult {
  ok: boolean;
  operation: string;
  result: unknown;
  errors: string[];
}


// ===== common.ts =====
// Helpers shared by all kernel operations. Ported from the Python
// pipeline; each function names its Python counterpart.

// prompt_builder._ESCAPE_MAP / str.translate({"&","<",">"})
function escapeXml(s: string): string {
  return s.replace(/[&<>]/g, (c: string): string =>
    c === "&" ? "&amp;" : c === "<" ? "&lt;" : "&gt;"
  );
}

// prompt_builder.wrap_user_text (review_id always supplied by L0).
function wrapUserText(text: string, reviewId: string): string {
  if (!reviewId) throw new Error("review_id must not be empty");
  if (/["'<>& \t\n\r]/.test(reviewId)) {
    throw new Error(`review_id contains a disallowed character: ${reviewId}`);
  }
  return `<user_review id="${reviewId}">${escapeXml(text)}</user_review>`;
}

// Python: _JSON_OBJECT_RE = re.compile(r"\{.*\}", re.DOTALL) — greedy,
// first "{" to last "}".
function extractJsonObjectText(text: string): string | null {
  const start = text.indexOf("{");
  const end = text.lastIndexOf("}");
  if (start < 0 || end < start) return null;
  return text.slice(start, end + 1);
}

// Python: _repair_unescaped_string_quotes. JS reports the failing
// position only in the error message ("... at position N"); when the
// runtime gives no position the repair is skipped.
function repairUnescapedStringQuotes(raw: string, maxIters = 32): string {
  let s = raw;
  for (let k = 0; k < maxIters; k++) {
    try {
      JSON.parse(s);
      return s;
    } catch (err) {
      const msg = String((err as Error).message || err);
      const m = /position (\d+)/.exec(msg);
      const looksLikeDelimiter =
        /Expected ',' or '}'|Expected ',' or ']'|Expected double-quoted property name|Unexpected string|Unexpected token/.test(
          msg
        );
      if (!m || !looksLikeDelimiter) return s;
      const pos = parseInt(m[1], 10);
      let i = pos - 1;
      while (i >= 0 && s[i] !== '"') i--;
      if (i < 0) return s;
      let backslashes = 0;
      let j = i - 1;
      while (j >= 0 && s[j] === "\\") {
        backslashes++;
        j--;
      }
      if (backslashes % 2 === 1) return s;
      s = s.slice(0, i) + "\\" + s.slice(i);
    }
  }
  return s;
}

interface ParsedObject {
  ok: boolean;
  data: { [k: string]: unknown } | null;
  error: string | null;
}

// Extract the JSON object from a model response, with one repair pass.
function parseModelJson(text: string): ParsedObject {
  const raw = extractJsonObjectText(text);
  if (raw === null) return { ok: false, data: null, error: "no JSON object found in response" };
  let data: unknown;
  try {
    data = JSON.parse(raw);
  } catch (first) {
    const repaired = repairUnescapedStringQuotes(raw);
    if (repaired === raw) {
      return { ok: false, data: null, error: `malformed JSON: ${String((first as Error).message)}` };
    }
    try {
      data = JSON.parse(repaired);
    } catch (second) {
      return {
        ok: false,
        data: null,
        error: `malformed JSON: ${String((first as Error).message)}; repaired retry failed: ${String(
          (second as Error).message
        )}`,
      };
    }
  }
  if (data === null || typeof data !== "object" || Array.isArray(data)) {
    return { ok: false, data: null, error: "expected a JSON object" };
  }
  return { ok: true, data: data as { [k: string]: unknown }, error: null };
}

function isInt(v: unknown): boolean {
  return typeof v === "number" && Number.isInteger(v);
}

function isNonEmptyString(v: unknown): boolean {
  return typeof v === "string" && v.trim().length > 0;
}

// Python json.dumps(x, ensure_ascii=False) default separators are
// (", ", ": "); JSON.stringify uses none. Only needed where a Python
// string was built from json.dumps; callers say so explicitly.
function pyJsonDumps(value: unknown): string {
  if (value === null) return "null";
  if (typeof value === "string") return JSON.stringify(value);
  if (typeof value === "number" || typeof value === "boolean") return JSON.stringify(value);
  if (Array.isArray(value)) return "[" + value.map((x: unknown): string => pyJsonDumps(x)).join(", ") + "]";
  const obj = value as { [k: string]: unknown };
  return (
    "{" +
    Object.keys(obj)
      .map((k: string): string => JSON.stringify(k) + ": " + pyJsonDumps(obj[k]))
      .join(", ") +
    "}"
  );
}

// Python "{:.2f}".format(x) (round-half-even differences are negligible
// for the values the pipeline formats).
function fmt2(x: number): string {
  return x.toFixed(2);
}

function uniqueInOrder(xs: string[]): string[] {
  const out: string[] = [];
  for (const x of xs) if (out.indexOf(x) < 0) out.push(x);
  return out;
}

// InsightCluster.evidence_review_ids_for
function evidenceReviewIdsFor(
  representativeReviewIds: string[] | undefined,
  quoteIdxs: number[]
): string[] {
  if (!representativeReviewIds || representativeReviewIds.length === 0) return [];
  const seen: string[] = [];
  for (const idx of quoteIdxs) {
    const rid = representativeReviewIds[idx];
    if (rid !== undefined && seen.indexOf(rid) < 0) seen.push(rid);
  }
  return seen;
}


// ===== dowody.ts =====
// Evidence lookup for the conversational agent: for each ranked
// violation of a reconciled verdict, which reviews and quotes support
// it, or whether it rests on the product artifact only.



interface DwEntry {
  rank: number;
  heuristic: string;
  severity: number;
  basis: "quotes" | "artifact_only";
  reviews: { review_id: string; quotes: string[]; text: string | null }[];
}

function dwEvidence(
  cluster: InsightCluster,
  reconciled: ReconciledVerdict,
  heuristic: string | null,
  utteranceTexts: { [id: string]: string } | null
): DwEntry[] {
  const repIds = cluster.representative_review_ids || [];
  const out: DwEntry[] = [];
  reconciled.ranked_violations.forEach((v, i: number): void => {
    if (heuristic && v.heuristic !== heuristic && v.heuristic.indexOf(heuristic) < 0) return;
    const reviews = v.evidence_review_ids.map((rid: string) => ({
      review_id: rid,
      quotes: cluster.representative_quotes.filter((_q: string, k: number): boolean => repIds[k] === rid),
      text: utteranceTexts && utteranceTexts[rid] !== undefined ? utteranceTexts[rid] : null,
    }));
    out.push({
      rank: i + 1,
      heuristic: v.heuristic,
      severity: v.severity,
      basis: reviews.length ? "quotes" : "artifact_only",
      reviews,
    });
  });
  return out;
}

// Plain-language summary the agent can return as is.
function dwSummary(entries: DwEntry[]): string {
  if (!entries.length) return "Nie znaleziono takiego ustalenia w uzgodnionym rankingu.";
  return entries
    .map((e: DwEntry): string => {
      const head = `${e.rank}. ${e.heuristic} (dotkliwość ${e.severity})`;
      if (e.basis === "artifact_only") return `${head}: brak cytatu klienta, ustalenie oparte tylko na artefakcie produktu.`;
      const parts = e.reviews.map((r) => `${r.review_id}: ${r.quotes.map((q: string) => `„${q}”`).join("; ")}`);
      return `${head}: ${e.reviews.length} recenzj${e.reviews.length === 1 ? "a" : "e"} — ${parts.join(" · ")}`;
    })
    .join("\n");
}


// ===== entry_dowody.ts =====
// AD_Dowody — evidence lookup for the conversational agent's tool flow.




function main(workbook: ExcelScript.Workbook, operation: string, payload: string): string {
  const out: KernelResult = { ok: true, operation, result: null, errors: [] };
  try {
    const p = JSON.parse(payload || "{}") as { [k: string]: unknown };
    if (operation !== "dowody") throw new Error(`unknown operation: ${operation}`);
    const entries = dwEvidence(
      p.cluster as InsightCluster,
      p.reconciled as ReconciledVerdict,
      typeof p.heuristic === "string" && p.heuristic ? (p.heuristic as string) : null,
      (p.utterance_texts as { [id: string]: string }) || null
    );
    out.result = { entries, summary: dwSummary(entries) };
  } catch (e) {
    out.ok = false;
    out.errors.push(String((e as Error).message || e));
  }
  return JSON.stringify(out);
}
